package com.railway.filter;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.Set;
public class AuthFilter implements Filter {private static final Set<String> PROTECTED=Set.of("/booking","/my-bookings","/booking-details","/cancel-booking","/admin","/admin-add-train");public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;HttpServletResponse s=(HttpServletResponse)res;String path=r.getServletPath();Object user=r.getSession(false)==null?null:r.getSession(false).getAttribute("user");if(PROTECTED.contains(path)&&user==null){s.sendRedirect(r.getContextPath()+"/login?next="+java.net.URLEncoder.encode(path,java.nio.charset.StandardCharsets.UTF_8));return;}if(path.startsWith("/admin")&&user instanceof com.railway.model.User u&&!"ADMIN".equals(u.getRole())){s.sendError(403);return;}chain.doFilter(req,res);}}
